15		mustSetMax(t, e, "B", 1_000)
16		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
17		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 20}, 1)
18		return e
19	}
20	
21	func TestAmountLimitDisabledByDefault(t *testing.T) {
22		e := setupAmt(t)
23		id := mustBuy(t, e, "A", 5, 10)
