503	func TestAmountOverflowOnSetKeepsRiskSnapshot(t *testing.T) {
504		// 金额占用与日内净值是两种口径：设置金额上限因金额合计溢出被拒时，
505		// 拒绝记录仍须保留当时的完整日内风险快照，与开日后的其他拒绝记录一致。
506		e, _ := NewEngine(1000)
507		mustSetMax(t, e, "A", 100)
508		mustSetMax(t, e, "B", 100)
509		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
510		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: math.MaxInt64}, 1)
511		aID := mustBuy(t, e, "A", 10, 10)
512		if _, err := e.Fill(Trade{TradeID: 1, OrderID: aID, Symbol: "A", Side: Buy, Price: 10, Qty: 10}); err != nil {
513			t.Fatal(err)
514		}
515		// 开日 7、亏损上限 100：基准净值 = 现金 900 + 持仓 10×10 = 1000。
516		if err := e.StartTradingDay(7, 100); err != nil {
517			t.Fatal(err)
518		}
519		// A 跌到 9：净值 990，亏损 10，尚未限制增险。
520		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: 9}, 1)
521		if st := e.RiskStatus(); !st.Open || st.Day != 7 || st.Baseline != 1000 ||
522			st.Equity != 990 || st.Loss != 10 || st.LossLimit != 100 || st.Restricted {
523			t.Fatalf("前置风险状态错误: %+v", st)
524		}
525		// 未启用金额上限时接受 B 的买单：只占用 2 现金，不改变净值；
526		// 其金额占用 2 × max(1, MaxInt64) 无法表示。
527		bID := mustBuy(t, e, "B", 2, 1)
528	
529		before := len(e.Records())
530		canceled, err := e.SetPositionAmountLimit(100)
531		if !errors.Is(err, ErrInt64Overflow) {
532			t.Fatalf("金额占用溢出必须返回包装 ErrInt64Overflow 的错误，实际 %v", err)
533		}
534		if canceled != nil {
535			t.Fatalf("溢出设置不得撤单: %v", canceled)
536		}
537	
538		// 只新增一条拒绝记录，且携带开日时的完整风险快照。
539		if len(e.Records()) != before+1 {
540			t.Fatalf("溢出设置只能增加一条记录: %d -> %d", before, len(e.Records()))
541		}
542		rec := e.Records()[before]
543		if rec.Kind != RecordRejected {
544			t.Fatalf("新增记录必须是拒绝: %+v", rec)
545		}
546		if rec.RiskDay != 7 || rec.RiskBaseline != 1000 || rec.RiskEquity != 990 ||
547			rec.RiskLoss != 10 || rec.RiskLimit != 100 || rec.RiskRestrict {
548			t.Fatalf("拒绝记录必须保留拒绝发生时的日内风险快照: %+v", rec)
549		}
550		// 金额上限启用状态与上限值保留调用前口径（未启用、零值），申请值只在原因中。
551		if rec.AmtEnabled || rec.AmtLimit != 0 {
552			t.Fatalf("记录中的金额上限状态必须保留调用前口径: %+v", rec)
553		}
554		if !strings.Contains(rec.Reason, "100") {
555			t.Fatalf("拒绝原因必须说明申请值与金额越界: %q", rec.Reason)
556		}
557	
558		// 整体不生效：不启用上限，现金、持仓、订单与占用均保持调用前状态。
559		if st := e.PositionAmountStatus(); st.Enabled {
560			t.Fatalf("溢出后设置不得生效: %+v", st)
561		}
562		if e.Cash() != 900 || e.ReservedCash() != 2 || e.Position("A") != 10 {
563			t.Fatalf("现金、占用与持仓必须保持调用前状态: cash=%d reserved=%d pos=%d",
564				e.Cash(), e.ReservedCash(), e.Position("A"))
565		}
566		if o, _ := e.Order(bID); o.Status != StatusPending || o.Remaining() != 2 {
567			t.Fatalf("B 买单必须保持待成交: %+v", o)
568		}
569		if st := e.RiskStatus(); st.Restricted {
570			t.Fatalf("溢出设置不得触发限制: %+v", st)
571		}
572	
573		// 后续报价、亏损上限调整与开启新交易日不得改写已保存的拒绝记录。
574		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: 8}, 1)
575		if err := e.SetLossLimit(50); err != nil {
576			t.Fatal(err)
577		}
578		if err := e.StartTradingDay(8, 1000); err != nil {
579			t.Fatal(err)
580		}
581		again := e.Records()[before]
582		if again.RiskDay != 7 || again.RiskBaseline != 1000 || again.RiskEquity != 990 ||
583			again.RiskLoss != 10 || again.RiskLimit != 100 || again.RiskRestrict {
584			t.Fatalf("已保存的拒绝记录不得被后续变化改写: %+v", again)
585		}
586	}
