666		for i := range recs {
667			if recs[i].AmtQuoteRefs != nil {
668				recs[i].AmtQuoteRefs[0].Price = 999
669				recs[i].AmtTotal = 1
670			}
671		}
672		again := lastAmountRecord(t, e, RecordCanceled)
673		if again.AmtQuoteRefs[0].Price == 999 || again.AmtTotal == 1 {
674			t.Fatalf("内部记录不得被查询副本改写: %+v", again)
675		}
