726		mustSetMax(t, e, "A", 1_000)
727		mustSetMax(t, e, "B", 1_000)
728		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 70, Price: 10}, 1)
729		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 20}, 1)
730		bid := mustBuy(t, e, "B", 5, 20) // 占用 100，达成持仓前置
731		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "B", Side: Buy, Price: 20, Qty: 5}); err != nil {
732			t.Fatal(err)
733		}
734		if _, err := e.SetPositionAmountLimit(150); err != nil {
735			t.Fatal(err)
736		}
737		// B 持仓 100；A 买单 6 股限价 5，按报价 10 占用 60，申请后 160 > 150。
738		if _, err := e.Buy("A", 6, 5); err == nil {
739			t.Fatal("必须拒绝")
740		}
741		rec := lastAmountRecord(t, e, RecordRejected)
742		if rec.AmtApplyTotal != 160 || rec.AmtTotal != 100 {
743			t.Fatalf("拒绝快照金额错误: %+v", rec)
744		}
745		var hasA, hasB bool
746		for _, rf := range rec.AmtQuoteRefs {
747			if rf.Symbol == "A" && rf.Seq == 1 && rf.Moment == 70 && rf.Price == 10 {
748				hasA = true
749			}
750			if rf.Symbol == "B" && rf.Seq == 1 && rf.Price == 20 {
751				hasB = true
752			}
753		}
754		if !hasA || !hasB || len(rec.AmtQuoteRefs) != 2 {
755			t.Fatalf("报价定位必须包含申请合约 A 与持仓合约 B: %+v", rec.AmtQuoteRefs)
756		}
757	}
758	
759	func lastAmountRecord(t *testing.T, e *Engine, kind RecordKind) Record {
760		t.Helper()
761		for i := len(e.records) - 1; i >= 0; i-- {
762			if e.records[i].Kind == kind && e.records[i].AmtEnabled {
763				return e.records[i]
764			}
765		}
766		t.Fatal("不存在携带金额快照的记录")
767		return Record{}
768	}
